export type HeadersLike = {
  get(name: string): string | null;
};

export const DEFAULT_CREATE_LINK_RATE_LIMIT = 5;
export const DEFAULT_CREATE_LINK_RATE_LIMIT_WINDOW_MS = 60_000;

type RateLimitEntry = {
  count: number;
  resetAt: number;
};

export class RateLimiter {
  private readonly storage = new Map<string, RateLimitEntry>();

  constructor(
    private readonly limit: number,
    private readonly windowMs: number,
  ) {}

  isAllowed(key: string): boolean {
    const now = Date.now();
    const entry = this.storage.get(key);

    if (!entry || entry.resetAt <= now) {
      this.storage.set(key, { count: 1, resetAt: now + this.windowMs });
      return true;
    }

    if (entry.count >= this.limit) {
      return false;
    }

    entry.count += 1;
    return true;
  }
}

export function getClientIp(headers: HeadersLike): string {
  const forwardedFor = headers.get("x-forwarded-for")?.split(",")[0]?.trim();

  if (forwardedFor) {
    return forwardedFor;
  }

  return headers.get("x-real-ip")?.trim() ?? "unknown";
}

const defaultRateLimiter = new RateLimiter(
  DEFAULT_CREATE_LINK_RATE_LIMIT,
  DEFAULT_CREATE_LINK_RATE_LIMIT_WINDOW_MS,
);

export function isRequestRateLimited(
  userId: string,
  headers: HeadersLike,
): boolean {
  const clientIp = getClientIp(headers);

  return (
    defaultRateLimiter.isAllowed(`user:${userId}`) &&
    defaultRateLimiter.isAllowed(`ip:${clientIp}`)
  );
}
